const item = $input.first().json;
const src = item.body || item; // handles 'Full Response' wrapping under .body
const raw = src.candidates?.[0]?.content?.parts?.[0]?.text
         || item.message?.content
         || item.content
         || item.text;

if (!raw) {
  throw new Error('No text found. Top-level keys were: ' + JSON.stringify(Object.keys(item)));
}

const clean = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
const parsed = JSON.parse(clean);
return [{ json: parsed }];

const items = $input.all();
const images = items.map(i => i.json.image_base64);
return [{ json: { images } }];
